  settings:'<path d="m6 1-.5 2-2 .8-1.8-.5L.7 5l1.4 1.5v3L.7 11l1 1.7 1.8-.5 2 .8.5 2h4l.5-2 2-.8 1.8.5 1-1.7-1.4-1.5v-3L15.3 5l-1-1.7-1.8.5-2-.8L10 1H6Z"/><circle cx="8" cy="8" r="2.2"/>',
  check:'<path d="m2.5 8 3.5 3.5 7.5-7.5"/>',
