  refresh:'<path d="M13 6a5.3 5.3 0 0 0-9-3L2 5m0-4v4h4m-3 5a5.3 5.3 0 0 0 9 3l2-2m0 4v-4h-4"/>',
  search:'<circle cx="6.5" cy="6.5" r="4.5"/><path d="m10 10 4 4"/>',
