function renderDoctor(){const result=state.diagnostic;let html=heading('环境检查','检查 APK 校验组件和凭据存储所需的系统环境。组件由工具安装，无需配置 Android SDK 或 JDK。',btn('重新检查环境','doctor')+btn('安装或修复检查组件','doctor-repair',result?.ready?'':'primary'))+notice()+taskBanner();if(!result)return html;html+='<div class="notice '+(result.ready?'success':'warn')+'">'+(result.ready?'环境检查通过，可以检查安装包。':'环境检查未通过。请查看下方项目，缺少 APK 校验组件时可点击安装或修复。')+'</div><div class="panel"><div class="panel-header">检查结果</div><ul class="check-list">'+(result.checks||[]).map(check=>'<li>'+badge(check.status==='ok'?'可用':check.status==='missing'?'未安装':check.status==='blocked'?'暂时无法检查':'检查未通过',check.status==='ok'?'success':'warn')+'<div class="check-content"><div class="check-title">'+esc(check.name||check.id)+'</div><div class="check-detail">'+esc(check.message||'')+'</div></div></li>').join('')+'</ul></div><details class="technical-details"><summary>版本与运行信息</summary><dl class="summary-grid"><div class="summary-item"><dt>版本</dt><dd>'+esc(result.version||'—')+'</dd></div><div class="summary-item"><dt>Node.js</dt><dd>'+esc(result.runtime||'—')+'</dd></div><div class="summary-item"><dt>系统 / 架构</dt><dd>'+esc(result.platform||'')+' / '+esc(result.arch||'')+'</dd></div></dl></details>';return html;}
function renderProtocols(){return heading('商店支持说明','提交、审核和上架分别记录，部分渠道的审核和上架状态需要人工核对。')+notice()+'<div class="panel"><div class="table-wrap"><table><thead><tr><th>商店</th><th>审核结果</th><th>上架结果</th><th>更新说明长度上限</th></tr></thead><tbody>'+state.protocols.map(row=>'<tr><td><strong>'+esc(row.name||names[row.channel])+'</strong></td><td>'+esc(row.review_query?'可自动查询':'到后台查看')+'</td><td>'+esc(row.availability_query?'可自动查询':'到后台查看')+'</td><td>'+esc(row.release_notes_max)+' 字符</td></tr>').join('')+'</tbody></table></div></div><p class="footnote">“可自动查询”表示工具能从商店接口查询本次版本的状态。无法自动查询时，请到商店后台核对，再保存人工核对记录。</p>';}

function credentialField(spec) {
  const key=spec.key,label=esc(spec.label),required=spec.optional?'（可选）':'<span class="required" aria-hidden="true">*</span>';
  if(!spec.material)return '<div class="field"><label for="credential-'+key+'">'+label+required+'</label><div class="credential-input"><input type="password" id="credential-'+key+'" data-credential-secret="'+key+'" autocomplete="new-password" spellcheck="false" autocapitalize="off" autocorrect="off" maxlength="65536"><button type="button" class="btn small" data-action="credential-reveal" data-control="credential-'+key+'" aria-pressed="false">显示内容</button></div></div>';
  const content='<div class="field credential-material" data-credential-material="'+key+'"><label for="credential-mode-'+key+'">'+label+required+'</label><select id="credential-mode-'+key+'" data-credential-mode="'+key+'"><option value="text">直接粘贴 '+esc(spec.material)+' 内容</option><option value="file">使用本地文件路径</option></select><div class="credential-method" data-credential-file-panel="'+key+'"><label class="field-label" for="credential-file-'+key+'">文件绝对路径</label><input type="text" id="credential-file-'+key+'" data-credential-file="'+key+'" autocomplete="off" spellcheck="false" autocorrect="off" maxlength="4096" placeholder="/绝对路径/'+(spec.material==='PEM'?'public-key.pem':'account.json')+'"><span class="hint">文件须属于当前用户，权限为 0600。工具会先检查文件权限，再读取内容。</span></div><div class="credential-method" data-credential-text-panel="'+key+'" hidden><div class="credential-label-row"><label class="field-label" for="credential-text-'+key+'">'+esc(spec.material)+' 内容</label><button type="button" class="btn small" data-action="credential-reveal" data-control="credential-text-'+key+'" aria-pressed="false">显示内容</button></div><textarea id="credential-text-'+key+'" class="credential-secret masked" data-credential-secret="'+key+'" autocomplete="off" spellcheck="false" autocapitalize="off" autocorrect="off" maxlength="65536" rows="5" placeholder="粘贴完整 '+esc(spec.material)+' 内容，保留原有换行。"></textarea><span class="hint">从商店下载的 API 材料中复制完整内容。内容默认隐藏，提交或关闭表单后清空。</span></div></div>';
  return spec.optional?'<details class="credential-optional"><summary>'+label+'（可选）</summary>'+content+'</details>':content;
}
function syncCredentialModes(form) {
  for(const select of form.querySelectorAll('[data-credential-mode]')){
    const field=select.dataset.credentialMode;
    form.querySelector('[data-credential-file-panel="'+field+'"]').hidden=select.value!=='file';
    form.querySelector('[data-credential-text-panel="'+field+'"]').hidden=select.value!=='text';
  }
}
function clearCredentialForm(form) {
  if(!form)return;
  for(const control of form.querySelectorAll('input,textarea')){control.value='';control.defaultValue='';control.removeAttribute('value');if(control.tagName==='TEXTAREA')control.textContent='';if(control.matches('input[data-credential-secret]'))control.type='password';if(control.tagName==='TEXTAREA')control.classList.add('masked');}
  form.reset();syncCredentialModes(form);
  for(const button of form.querySelectorAll('[data-action="credential-reveal"]')){button.textContent='显示内容';button.setAttribute('aria-pressed','false');}
}
function closeModal() {
  const form=$('#credentials-form');
  const channel=form?.dataset.channel,account=form?.dataset.account;
  clearCredentialForm(form);
  $('#modal').replaceChildren();
  if(channel&&account)[...document.querySelectorAll('[data-action="credential-update"]')].find(button=>button.dataset.channel===channel&&button.dataset.account===account)?.focus();
}
function openCredentials(channel,account,context=null) {
  closeModal();
  $('#toast').hidden=true;clearTimeout(toastTimer);
  state.credentialContext=context;
  const row=state.accounts.find(item=>item.channel===channel&&item.account===account);
  if(!row||!credentialSpecs[channel])return;
  $('#modal').innerHTML='<div class="modal-overlay"><section class="modal-dialog credential-dialog" role="dialog" aria-modal="true" aria-labelledby="credential-title" aria-describedby="credential-context"><div class="modal-heading"><h2 id="credential-title">'+esc(names[channel])+' · '+(row.saved?'更新凭据':'填写凭据')+'</h2><button type="button" class="modal-close" data-action="close-modal" aria-label="关闭">×</button></div><div class="modal-content"><div id="credential-context" class="credential-context"><div><span class="small-muted">渠道账号</span><strong>'+esc(row.client_id||account)+'</strong></div>'+(row.client_id?'<div><span class="small-muted">账号备注</span><span>'+esc(account)+'</span></div>':'')+'<div><span class="small-muted">关联应用</span><span>'+((row.app_names||row.apps.map(appName)).map(esc).join('、')||'暂未关联应用')+'</span></div></div><p class="footnote">填写商店 API 凭据。请使用已经签名的 APK，签名密钥由打包工具管理。'+(row.apps.length?'工具会尝试读取关联应用的商店资料。至少一个应用读取成功后保存凭据，各应用的检查结果可在应用页面查看。':'凭据通过格式检查后加密保存在本地。为应用选择此账号后，再检查能否读取该应用的商店资料。')+'</p><form id="credentials-form" autocomplete="off" data-channel="'+esc(channel)+'" data-account="'+esc(account)+'"><div id="credential-error" class="notice error" role="alert" hidden></div>'+credentialSpecs[channel].map(credentialField).join('')+'<div id="credential-progress" class="progress-label" role="status" hidden><span class="spinner"></span>正在检查并保存凭据…</div><div class="form-actions"><button type="submit" class="btn primary" id="credential-save">'+(row.apps.length?'验证并保存':'保存凭据')+'</button>'+btn('取消','close-modal')+'</div></form></div></section></div>';
  const form=$('#credentials-form');syncCredentialModes(form);
  [...form.querySelectorAll('input,textarea,select')].find(control=>control.getClientRects().length)?.focus();
}
async function saveCredentials(form) {
  if(state.busy)return;
  const context=state.credentialContext;const standalone=!state.accounts.find(row=>row.channel===form.dataset.channel&&row.account===form.dataset.account)?.apps.length;
  let payload;
  let failed=false;
  let saved=false;
  const rejectInput=(code,label)=>{const error=new Error('credential input');error.credentialIssue=code;error.credentialLabel=label;throw error;};
  const setError=text=>{if(!form.isConnected)return;const error=form.querySelector('#credential-error');error.textContent=text;error.hidden=false;};
  try{
    const credentials={},files={};
    payload={channel:form.dataset.channel,account:form.dataset.account,credentials,files};
    const specs=credentialSpecs[payload.channel];
    if(!specs)rejectInput('account');
    for(const spec of specs){
      const file=spec.material&&form.querySelector('[data-credential-mode="'+spec.key+'"]').value==='file';
      const control=file?form.querySelector('[data-credential-file="'+spec.key+'"]'):form.querySelector('[data-credential-secret="'+spec.key+'"]');
      const value=file?control.value.trim():control.value;
      if(!value.trim()){if(spec.optional)continue;rejectInput('fields',spec.label);}
      if(file&&!value.startsWith('/'))rejectInput('file',spec.label);
      const bytes=new TextEncoder().encode(value),tooLarge=bytes.length>(file?4096:65536);bytes.fill(0);
      if(tooLarge)rejectInput('size',spec.label);
      (file?files:credentials)[spec.key]=value;
    }
    clearCredentialForm(form);
    form.querySelector('#credential-error').hidden=true;
    form.querySelector('#credential-progress').hidden=false;
    for(const control of form.querySelectorAll('input,textarea,select,button'))control.disabled=true;
    state.busy=true;state.progress='正在检查并保存账号凭据…';state.notice=null;render();
    const result=await api('accounts.update',payload);
    if(result.updated!==true)throw new Error('凭据保存尚未确认。');
    saved=true;
    closeModal();
    state.accounts=(await api('accounts.list')).accounts||[];
    await refreshApps();
    await afterCredentialSaved(context);
    toast(standalone?'凭据已加密保存。为应用选择此账号后，再检查账号访问。':'凭据已加密保存，请在应用页面查看账号访问检查结果。');
  }catch(error){
    failed=true;
    clearCredentialForm(form);
    const inputHint=error.credentialLabel?(error.credentialIssue==='fields'?'请填写'+error.credentialLabel+'。':error.credentialIssue==='file'?'请为'+error.credentialLabel+'填写本地文件的绝对路径。':error.credentialIssue==='size'?error.credentialLabel+'过长，请检查输入内容或文件路径。':''):'';
    const message=saved?'凭据已保存，账号列表刷新未完成，请刷新页面查看。':(inputHint||credentialHints[error.credentialIssue]||'凭据验证或保存未完成。请检查材料、账号权限和钥匙串后重新输入。')+' 已输入内容已清空。';
    if(form.isConnected)setError(message);else state.notice={type:saved?'warn':'error',text:saved?message:'凭据未保存，请重新打开表单填写。'};
  }finally{
    if(payload){for(const values of [payload.credentials,payload.files])for(const key of Object.keys(values||{})){values[key]='';delete values[key];}}
    state.busy=false;state.progress='';
    if(form.isConnected){form.querySelector('#credential-progress').hidden=true;for(const control of form.querySelectorAll('input,textarea,select,button'))control.disabled=false;}
    render();
    if(failed&&form.isConnected)[...form.querySelectorAll('input,textarea,select')].find(control=>control.getClientRects().length)?.focus();
    if(navigationPending){navigationPending=false;await navigate();}
  }
}

function appDefault(){return{schema_version:2,project_id:'app-'+crypto.randomUUID().slice(0,8),display_name:'',package_name:'',channels:[]};}
function rowDefault(channel,pkg){const available=state.accounts.filter(row=>row.channel===channel);const saved=available.length===1?available[0]:null;return{channel,account:saved?.account||(available.length?channel+'-'+crypto.randomUUID().slice(0,8):channel+'-main'),app_id:['xiaomi','oppo','vivo'].includes(channel)?pkg:'',...(fieldLabels[channel]?{client_id:saved?.client_id||''}:{})};}
function captureSetupForm(){const setup=state.setup,form=$('#setup-form');if(!setup||!form)return;for(const key of ['display_name','package_name','project_id']){const control=form.querySelector('[name="'+key+'"]');if(control)setup.value[key]=control.value.trim();}const row=setup.value.channels[setup.index];if(setup.step===3&&row){for(const key of ['app_id','account','client_id','icon_path','privacy_url']){const control=form.querySelector('[name="channel-'+key+'"]');if(control)row[key]=control.value.trim();}if(['xiaomi','oppo','vivo'].includes(row.channel))row.app_id=setup.value.package_name;}}
function rowError(row,pkg){const id=value=>typeof value==='string'&&/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(value);if(!id(row.account))return '高级设置中的账号备注格式无效：须以字母或数字开头，只能包含字母、数字、点、横线和下划线，最多 128 个字符。';if(!['xiaomi','oppo','vivo'].includes(row.channel)&&!id(row.app_id))return '商店应用编号（App ID）格式无效：须以字母或数字开头，只能包含字母、数字、点、横线和下划线，最多 128 个字符。';if(fieldLabels[row.channel]){const client=row.client_id,valid=row.channel==='xiaomi'?typeof client==='string'&&client.length>0&&client.trim()===client&&new TextEncoder().encode(client).length<=256&&!/[\u0000-\u001f\u007f\u2028\u2029]/u.test(client):id(client);if(!valid)return row.channel==='xiaomi'?'请填写开发者账号（userName），最多 256 字节，不含控制字符。':fieldLabels[row.channel][0]+'（'+fieldLabels[row.channel][1]+'）格式无效：须以字母或数字开头，只能包含字母、数字、点、横线和下划线，最多 128 个字符。';}if(row.channel==='xiaomi'){const icon=row.icon_path;if(!icon?.startsWith('/')||icon.length>4096||new TextEncoder().encode(icon).length>4096||/[\u0000-\u001f\u007f\u2028\u2029]/u.test(icon)||icon.includes('//')||/(?:^|\/)\.{1,2}(?:\/|$)/.test(icon))return '请填写应用图标的完整绝对路径或选择图标图片；路径不要包含 .、.. 或连续斜线。';try{const url=new URL(row.privacy_url);if(new TextEncoder().encode(row.privacy_url).length>4096||url.protocol!=='https:'||url.search||url.hash||url.username||url.password)throw new Error();}catch{return '请填写不带查询参数或片段的 HTTPS 隐私政策网页地址。';}}return '';}
function readyRow(row,pkg){return !rowError(row,pkg);}
function validateBasics(){const value=state.setup.value;if(!value.display_name?.trim())throw new Error('请填写应用名称，例如“阅读助手”。');if(new TextEncoder().encode(value.display_name).length>256||/[\u0000-\u001f\u007f\u2028\u2029]/u.test(value.display_name))throw new Error('应用名称须不含控制字符，且不超过 256 字节。');if(value.package_name.length>255||!/^[A-Za-z][A-Za-z0-9_]*(?:\.[A-Za-z][A-Za-z0-9_]*)+$/.test(value.package_name))throw new Error('请填写现有应用的 Android 包名，例如 com.example.app，最多 255 个字符。');if(!/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(value.project_id))throw new Error('高级设置中的命令行短名格式无效：须以字母或数字开头，只能包含字母、数字、点、横线和下划线，最多 128 个字符。');}
async function loadSetup(key,query){await refreshApps();state.accounts=(await api('accounts.list')).accounts||[];const app=key==='new'?null:selectedApp(key);if(key!=='new'&&!app)throw new Error('找不到这个应用，请从应用列表选择。');const channelsMode=query.has('channel')||query.has('channels');const draftKind=key!=='new'&&!channelsMode?'app-details':'app';const draftKey=key==='new'?'new-app':key;const saved=await api('drafts.get',{kind:draftKind,id:draftKey});const value=saved.draft||app&&structuredClone(app)||appDefault();value.display_name||=app?.display_name||app?.project_id||'';value.channels||=[];if(channelsMode&&app){value.display_name=app.display_name||app.project_id;value.package_name=app.package_name;value.project_id=app.project_id;}const mode=channelsMode||key==='new'&&selectedApp(value.project_id)?'channels':'basics';const step=mode==='basics'?1:query.has('channel')?3:query.has('add')?2:value.channels.length?3:2;let index=Math.max(0,value.channels.findIndex(row=>row.channel===query.get('channel')));if(!query.has('channel')&&step===3)index=Math.max(0,value.channels.findIndex(row=>!overview(value.project_id).channels.some(item=>item.channel===row.channel&&item.saved&&item.connected)));state.setup={key:draftKey,draftKind,mode,value,step,index,stage:'editing',persistable:true,returnTo:query.get('return')==='publish'?'publish':''};state.app=app;state.view='setup';markSave(saved.draft?mode==='basics'?'已恢复应用资料草稿':'已恢复发布渠道配置草稿':'更改会自动保存到本地');}
async function setupNext(){
  captureSetupForm();validateBasics();const setup=state.setup;
  if(setup.mode==='basics'){
    await saveSetup(true);
    const existing=selectedApp(setup.value.project_id);
    await api('apps.save',{app:{...setup.value,channels:existing?.channels||[]},replace:Boolean(existing)});
    setup.persistable=false;
    await clearSavedDraft(setup.draftKind,setup.key);
    if(setup.key==='new-app')state.newAppDraft=null;
    await refreshApps();
    location.hash='#/app/'+encodeURIComponent(setup.value.project_id);toast('应用资料已保存，可以从应用中添加发布渠道。');return;
  }
  if(!setup.value.channels.length)throw new Error('请选择要为这个应用添加的发布渠道。');
  setup.step=3;setup.index=Math.max(0,setup.value.channels.findIndex(row=>!selectedApp(setup.value.project_id)?.channels.some(item=>item.channel===row.channel)));
  history.replaceState(null,'','#/setup/'+encodeURIComponent(setup.value.project_id)+'?channels=1'+(setup.returnTo==='publish'?'&return=publish':''));
  await saveSetup(true);render();
}
async function connectSetupChannel(){captureSetupForm();validateBasics();const setup=state.setup,row=setup.value.channels[setup.index],error=rowError(row,setup.value.package_name);if(error)throw new Error(error+'已填写内容会保留。');await saveSetup(true);const existing=selectedApp(setup.value.project_id);const merged=new Map((existing?.channels||[]).map(item=>[item.channel,item]));for(const item of setup.value.channels)if(readyRow(item,setup.value.package_name))merged.set(item.channel,{...item,app_id:['xiaomi','oppo','vivo'].includes(item.channel)?setup.value.package_name:item.app_id});await api('apps.save',{app:{schema_version:2,project_id:setup.value.project_id,display_name:setup.value.display_name,package_name:setup.value.package_name,channels:[...merged.values()]},replace:Boolean(existing)});await refreshApps();state.accounts=(await api('accounts.list')).accounts||[];state.app=selectedApp(setup.value.project_id);if(state.setup!==setup)return;const account=state.accounts.find(item=>item.channel===row.channel&&item.account===row.account);if(account?.saved)await startJob('apps.check',{app_id:setup.value.project_id,channels:[row.channel]},{kind:'setup',appId:setup.value.project_id,channel:row.channel});else openCredentials(row.channel,row.account,{kind:'setup',key:setup.key,appId:setup.value.project_id,channel:row.channel});}
async function advanceSetup(channel){const setup=state.setup;if(!setup)return;const status=overview(setup.value.project_id).channels.find(row=>row.channel===channel);if(!status?.connected){state.notice={type:'warn',text:names[channel]+'的账号访问检查未通过。资料已保存，请检查商店应用资料、账号凭据或网络。'};render();return;}const next=setup.value.channels.findIndex((row,index)=>index>setup.index&&!setupStatus(row.channel));if(next>=0){setup.index=next;setup.step=3;}else if(setup.value.channels.every(row=>setupStatus(row.channel))){setup.stage='complete';setup.persistable=false;await clearSavedDraft(setup.draftKind||'app',setup.key);if(setup.key==='new-app')state.newAppDraft=null;}else{setup.stage='complete';}await saveSetupIfIncomplete();render();}
async function saveSetupIfIncomplete(){if(state.setup?.stage!=='complete')await saveSetup(true);}
async function afterCredentialSaved(context){if(context?.kind==='setup'&&state.setup?.key===context.key)await advanceSetup(context.channel);if(context?.kind==='repair'){if(context.releaseId)await refreshCachedRelease(context.releaseId);if(state.publish?.appId===context.appId){state.publish.plan=null;state.publish.phase=state.publish.mode==='retry'?'checking':'materials';state.publish.revision++;}state.notice={type:'info',text:names[context.channel]+'账号凭据已保存。原安装包、更新说明和其他渠道进度已保留，请重新检查后确认重试。'};}}
function newPublish(app,draft=null){return{appId:app.project_id,flowId:crypto.randomUUID(),persistable:true,mode:'new',channels:draft?.channels||app.channels.map(row=>row.channel),apks:draft?.apks||{},notes:draft?.release_notes||'',releaseId:draft?.release_id||null,release:null,phase:'materials',errors:{},checkError:'',plan:null,revision:0,uploading:{},restored:Boolean(draft),related:null};}
function draftFromPublish(p){return{app_id:p.appId,channels:[...p.channels],apks:Object.fromEntries(p.channels.filter(channel=>p.apks[channel]).map(channel=>[channel,p.apks[channel]])),release_notes:p.notes,...(p.releaseId?{release_id:p.releaseId}:{})};}
async function loadPublish(id,fresh=false){const app=selectedApp(id);if(!app)throw new Error('请先添加这个应用。');if(!app.channels.length){location.hash='#/setup/'+encodeURIComponent(id)+'?channels=1&add=1';toast('请先为这个应用添加发布渠道。');return;}const response=await api('drafts.get',{kind:'release',id});state.app=app;state.publish=newPublish(app,fresh?null:response.draft);if(state.publish.releaseId){const release=await refreshCachedRelease(state.publish.releaseId);if(release.has_writes||submitting(release.batch_id)){state.publish.persistable=false;await clearSavedDraft('release',id);state.release=release;state.view='release';history.replaceState(null,'','#/release/'+encodeURIComponent(release.batch_id));return;}state.publish.release=release;}state.view='publish';if(fresh){await saveRelease(true);history.replaceState(null,'','#/publish/'+encodeURIComponent(id));}markSave(response.draft&&!fresh?'已恢复本地发布草稿':'更改会自动保存到本地');}
function invalidatePublish(){const p=state.publish;if(!p)return;p.revision++;p.plan=null;p.checkError='';p.phase=p.mode==='retry'?'checking':'materials';}
async function beginChecks(){const p=state.publish;if(!p.channels.length)throw new Error('请至少选择一个提交渠道。');const missing=p.channels.filter(channel=>!p.apks[channel]);if(missing.length)throw new Error('请为'+missing.map(channel=>names[channel]).join('、')+'选择对应的安装包，或取消选择该渠道。');if(Object.keys(p.uploading).length)throw new Error('安装包还在保存到本地，请保存完成后检查。');const max=p.channels.includes('vivo')?200:500;if([...p.notes.trim()].length<5||[...p.notes].length>max)throw new Error('更新说明至少 5 个字符，当前渠道最多 '+max+' 个字符。');await saveRelease(true);p.plan=null;p.errors={};p.checkError='';p.phase='checking';render();await startJob('releases.prepare',{app_id:p.appId,apks:Object.fromEntries(p.channels.map(channel=>[channel,p.apks[channel]])),release_notes:p.notes,channels:p.channels},{kind:'publish',appId:p.appId,flowId:p.flowId,revision:p.revision});}
async function recheck(){const p=state.publish;if(!p.channels.length)throw new Error('请至少选择一个提交渠道。');p.plan=null;p.checkError='';if(!p.releaseId)return beginChecks();await startJob('releases.preflight',{release_id:p.releaseId,channels:p.channels},{kind:'publish',appId:p.appId,flowId:p.flowId,revision:p.revision});}
async function requestReview(){const p=state.publish;if(!p.channels.length)throw new Error('请至少选择一个提交渠道。');const payload={release_id:p.releaseId,channels:p.channels,...(p.attemptOnly?{attempt_only:true}:{})};await startJob('releases.review',payload,{kind:'publish',appId:p.appId,flowId:p.flowId,revision:p.revision});}
async function confirmSubmit(){const p=state.publish;if(!p?.plan||p.phase!=='confirm')return;const payload={release_id:p.releaseId,approval_plan:p.plan.approval_plan,...(p.attemptOnly?{attempt_only:true}:{})};p.phase='tracking';p.plan=null;render();let job;try{job=await startJob('releases.submit',payload,{kind:'submit',appId:p.appId});}catch(error){p.phase='checking';p.persistable=true;p.checkError='提交任务尚未启动，草稿已保留。重新检查后可再次确认。';throw error;}if(job&&p.mode!=='retry'){p.persistable=false;try{await clearSavedDraft('release',p.appId);}catch{state.notice={type:'warn',text:'提交任务已启动，原材料已保存在发布记录中。旧草稿暂未清理，请在发布记录中查看提交进度。'};}state.appReleaseDraft=null;}}
async function startNewRelease(id){const existing=(await api('drafts.get',{kind:'release',id})).draft;if(existing&&(Object.keys(existing.apks||{}).length||existing.release_notes)){closeModal();$('#modal').innerHTML='<div class="modal-overlay"><section class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="draft-title"><div class="modal-heading"><h2 id="draft-title">这个应用已有发布草稿</h2><button class="modal-close" type="button" data-action="close-modal" aria-label="关闭">×</button></div><div class="modal-content"><p>已保存 '+Object.keys(existing.apks||{}).length+' 个渠道的安装包。可以继续编辑已有草稿，也可以新建空白草稿。</p><div class="form-actions">'+link('继续编辑草稿','#/publish/'+encodeURIComponent(id),'primary')+btn('新建空白草稿','fresh-release','','data-app="'+id+'"')+'</div></div></section></div>';return;}location.hash='#/publish/'+encodeURIComponent(id)+'?new=1';}
async function editRelease(id){const release=await refreshCachedRelease(id);if(release.has_writes||!release.can_edit||submitting(id)){state.release=release;state.view='release';history.replaceState(null,'','#/release/'+encodeURIComponent(id));state.notice={type:'warn',text:'这次发布已经开始提交，原材料会保留。要更换安装包或更新说明，请新建发布草稿。'};render();return;}const value={app_id:release.project_id,channels:release.targets.map(row=>row.channel),apks:Object.fromEntries(release.targets.map(row=>[row.channel,row.artifact.path])),release_notes:release.release_notes,release_id:id};await api('drafts.save',{kind:'release',id:release.project_id,value});location.hash='#/publish/'+encodeURIComponent(release.project_id);}
async function retryChannel(id,channel){const release=await refreshCachedRelease(id),target=release.targets.find(row=>row.channel===channel);if(!target||target.recovery_required)throw new Error('请先检查'+names[channel]+'上次提交的结果，原记录仍保留。');if(!release.has_writes)return editRelease(id);state.release=release;state.app=selectedApp(release.project_id);state.publish={...newPublish(state.app),mode:'retry',channels:[channel],releaseId:id,release,notes:release.release_notes,apks:Object.fromEntries(release.targets.map(row=>[row.channel,row.artifact.path])),attemptOnly:true,phase:'checking'};state.view='publish';history.replaceState(null,'','#/retry/'+encodeURIComponent(id)+'/'+channel);await recheck();}
async function fixAccount(appId,channel,releaseId){state.accounts=(await api('accounts.list')).accounts||[];const release=releaseId?await refreshCachedRelease(releaseId):null;const target=release?.targets.find(row=>row.channel===channel)||selectedApp(appId)?.channels.find(row=>row.channel===channel);if(!target)throw new Error('请先保存'+names[channel]+'的商店应用和渠道账号资料。');const account=state.accounts.find(row=>row.channel===channel&&row.account===target.account);if(!account)throw new Error('未找到这次发布使用的渠道账号。原记录已保留，请在“渠道账号”中核对原账号。');openCredentials(channel,target.account,{kind:'repair',appId,releaseId,channel});}
function openManual(id,channel){const release=state.release||state.publish?.release;if(!release||release.batch_id!==id)return void work('正在读取发布记录…',async()=>{state.release=await refreshCachedRelease(id);openManual(id,channel);});closeModal();const waiting=release.targets.find(row=>row.channel===channel)?.recovery_required;$('#modal').innerHTML='<div class="modal-overlay"><section class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="manual-title"><div class="modal-heading"><h2 id="manual-title">'+esc(names[channel])+' · 人工核对并记录</h2><button class="modal-close" type="button" data-action="close-modal" aria-label="关闭">×</button></div><div class="modal-content"><ol class="business-steps"><li>打开你平时使用的'+esc(names[channel])+'开发者后台。</li><li>选择应用 <strong>'+esc(release.package_name)+'</strong>。</li><li>找到版本 <strong>'+esc(release.version_name)+'（'+esc(release.version_code)+'）</strong>，查看审核状态和当前在架版本。</li></ol>'+'<p class="footnote">人工核对记录与自动查询结果分别保存和展示。</p>'+(waiting?'<div class="notice warn">原请求可能已生效。记录审核或上架状态后，仍须核对原请求，才能确定是否可以重试。</div>':'')+'<form id="manual-form" data-release="'+id+'" data-channel="'+channel+'"><div class="form-grid"><div class="field"><label for="manual-review">核对的审核状态</label><select id="manual-review" name="review_state">'+Object.entries(reviewLabels).map(([value,label])=>'<option value="'+value+'">'+label+'</option>').join('')+'</select></div><div class="field"><label for="manual-live">核对的上架状态</label><select id="manual-live" name="availability_state">'+Object.entries(availabilityLabels).map(([value,label])=>'<option value="'+value+'">'+label+'</option>').join('')+'</select></div></div>'+field('核对时间','observed_at',localTime(),'','datetime-local',true)+field('核对来源','source',names[channel]+'开发者后台','例如该版本的审核记录或在架版本信息。','text',true)+'<div class="field"><label for="manual-note">补充记录（可选）</label><textarea id="manual-note" name="note" maxlength="2000" rows="3"></textarea></div><div class="form-actions"><button type="submit" class="btn primary">保存人工核对记录</button>'+btn('取消','close-modal')+'</div></form></div></section></div>';const previous=effectiveManual(release,release.targets.find(row=>row.channel===channel));$('#manual-review').value=previous?.review_state||'unknown';$('#manual-live').value=previous?.availability_state||'unknown';$('#manual-review').focus();}
async function navigate(){closeModal();flushDrafts();const generation=++routeGeneration;state.notice=null;const[route,search='']=(location.hash.replace(/^#\/?/,'')||'home').split('?');const parts=route.split('/').map(decodeURIComponent),query=new URLSearchParams(search);try{await refreshApps();if(generation!==routeGeneration)return;state.newAppDraft=(await api('drafts.get',{kind:'app',id:'new-app'})).draft;const section=parts[0];if(section==='setup'){await loadSetup(parts[1]||'new',query);}else if(section==='publish'){await loadPublish(parts[1],query.get('new')==='1');}else if(section==='retry'&&parts[1]&&parts[2]){await retryChannel(parts[1],parts[2]);}else if(section==='release'){state.release=await refreshCachedRelease(parts[1]);state.app=selectedApp(state.release.project_id);state.view='release';autoRefresh.set(parts[1],0);}else if(section==='accounts'){state.accounts=(await api('accounts.list')).accounts||[];state.view='accounts';state.app=null;}else if(section==='doctor'){state.diagnostic=await api('doctor');state.view='doctor';state.app=null;}else if(section==='protocols'){state.protocols=(await api('protocols')).channels||[];state.view='protocols';state.app=null;}else{const id=section==='app'?parts[1]:section==='home'&&state.apps.length===1?state.apps[0].project_id:null;if(id){state.app=selectedApp(id);if(!state.app)throw new Error('找不到这个应用，请从应用列表选择。');state.releases=(await api('releases.list',{app_id:id})).releases||[];state.appSetupDraft=(await api('drafts.get',{kind:'app',id})).draft;state.appReleaseDraft=(await api('drafts.get',{kind:'release',id})).draft;if(state.appReleaseDraft?.release_id&&state.releases.some(row=>row.batch_id===state.appReleaseDraft.release_id&&(row.has_writes||submitting(row.batch_id)))){await clearSavedDraft('release',id);state.appReleaseDraft=null;}state.view='app';if(section==='home')history.replaceState(null,'','#/app/'+encodeURIComponent(id));}else{state.app=null;state.view='apps';}}}catch(error){state.notice={type:'error',text:error.message||'页面暂时无法加载，本地资料仍保留。'};}finally{if(generation===routeGeneration)render();}}
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='account-form'){void saveAccountProfile(form);return;}if(form.id==='credentials-form'){void saveCredentials(form);return;}if(form.id==='setup-form'){void work('正在保存应用资料…',()=>state.setup.step===3?connectSetupChannel():setupNext());return;}if(form.id==='manual-form'){const values=new FormData(form);const payload={release_id:form.dataset.release,channel:form.dataset.channel,review_state:values.get('review_state'),availability_state:values.get('availability_state'),observed_at:new Date(String(values.get('observed_at'))).toISOString(),source:String(values.get('source')||''),note:String(values.get('note')||'')};closeModal();void work('正在保存人工核对记录…',async()=>{const result=await api('releases.manual',payload);state.release=result.release;state.view='release';history.replaceState(null,'','#/release/'+encodeURIComponent(result.release.batch_id));toast('人工核对记录已保存。');});}});
document.addEventListener('input',event=>{const target=event.target;if(target.matches('[data-credential-secret],[data-credential-file]')){const error=target.closest('form').querySelector('#credential-error');if(error)error.hidden=true;return;}if(target.closest('#setup-form')){captureSetupForm();void saveSetup();return;}if(target.id==='release-notes'&&state.publish){state.publish.notes=target.value;invalidatePublish();const counter=$('#notes-count');if(counter)counter.textContent=[...target.value].length+' / '+(state.publish.channels.includes('vivo')?'200':'500')+' 字符';void saveRelease();}});
async function handleChange(event,publish=state.publish,setupContext=state.setup){const target=event.target;try{if(target.id==='account-channel'){const form=target.closest('form'),previous=form.querySelector('#new-account-name').value.trim();openAccountProfile(target.value,channels.some(channel=>previous===channel+'-main')?'':previous);return;}if(target.dataset.credentialMode){const form=target.closest('form'),key=target.dataset.credentialMode;for(const control of form.querySelectorAll('[data-credential-file="'+key+'"],[data-credential-secret="'+key+'"]'))control.value='';const secret=form.querySelector('[data-credential-secret="'+key+'"]');secret.classList.add('masked');const reveal=form.querySelector('[data-control="'+secret.id+'"]');reveal.textContent='显示内容';reveal.setAttribute('aria-pressed','false');form.querySelector('#credential-error').hidden=true;syncCredentialModes(form);return;}if(target.dataset.setupSelect){captureSetupForm();const value=state.setup.value,channel=target.dataset.setupSelect;value.channels=target.checked?[...value.channels,rowDefault(channel,value.package_name)]:value.channels.filter(row=>row.channel!==channel);await saveSetup(true);render();return;}if(target.id==='account-choice'){captureSetupForm();const row=state.setup.value.channels[state.setup.index];if(target.value==='new'){row.account=row.channel+'-'+crypto.randomUUID().slice(0,8);if(fieldLabels[row.channel])row.client_id='';}else{const saved=state.accounts.find(item=>item.channel===row.channel&&item.account===target.value);row.account=saved.account;row.client_id=saved.client_id||state.apps.flatMap(app=>app.channels).find(item=>item.channel===row.channel&&item.account===saved.account)?.client_id||'';}await saveSetup(true);render();return;}if(target.id==='setup-icon'){const file=target.files[0];if(!file)return;const setup=setupContext;if(!setup||state.setup!==setup)return;const row=setup.value.channels[setup.index];state.progress='正在把应用图标保存到本地…';render();row.icon_path=await upload(file,'app-icon');if(state.setup===setup)await saveSetup(true);state.progress='';render();return;}if(target.dataset.publishChannel||target.dataset.checkChannel){const p=state.publish,channel=target.dataset.publishChannel||target.dataset.checkChannel;p.channels=target.checked?[...p.channels,channel]:p.channels.filter(item=>item!==channel);p.revision++;p.plan=null;if(target.dataset.publishChannel)p.phase='materials';render();await saveRelease(true);return;}if(target.dataset.apk){const file=target.files[0],p=publish,channel=target.dataset.apk;if(!file||!p||state.publish!==p)return;p.uploading[channel]=file.name;invalidatePublish();render();const saved=await upload(file);if(state.publish!==p||p.persistable===false)return;p.apks[channel]=saved;await persistDraft('release',p.appId,draftFromPublish(p),true);delete p.uploading[channel];render();return;}if(target.id==='notes-file'){const file=target.files[0];if(!file)return;if(file.size>65536)throw new Error('更新说明文件过大，请使用不超过 64 KiB 的 UTF-8 文本。');state.publish.notes=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());invalidatePublish();await saveRelease(true);render();}}catch(error){if(target.dataset.apk&&publish)delete publish.uploading[target.dataset.apk];state.progress='';state.notice={type:'error',text:error.message||'文件尚未保存，原材料仍保留，请重试。'};render();}}
document.addEventListener('change',event=>void handleChange(event));
document.addEventListener('click',event=>{const anchor=event.target.closest('a');if(anchor&&anchor.getAttribute('href')?.startsWith('#/'))closeModal();const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(action==='close-modal'){closeModal();return;}if(action==='credential-reveal'){const control=document.getElementById(button.dataset.control);if(!control)return;const visible=button.getAttribute('aria-pressed')!=='true';if(control.tagName==='INPUT')control.type=visible?'text':'password';else control.classList.toggle('masked',!visible);button.setAttribute('aria-pressed',String(visible));button.textContent=visible?'隐藏内容':'显示内容';return;}if(action==='add-account'){if(!state.busy)openAccountProfile();return;}if(action==='credential-update'){if(!state.busy)openCredentials(button.dataset.channel,button.dataset.account);return;}const execute=async()=>{switch(action){case'restart-setup':if(!confirm('放弃这份未完成的应用资料，添加另一个应用？已经保存的应用、渠道和本地凭据会保留。'))return;state.setup.persistable=false;await clearSavedDraft('app','new-app');state.newAppDraft=null;await loadSetup('new',new URLSearchParams());return render();case'setup-next':return setupNext();case'setup-back':captureSetupForm();state.setup.step=Math.max(2,state.setup.step-1);return render();case'setup-channel':captureSetupForm();await saveSetup(true);state.setup.index=Number(button.dataset.index);return render();case'setup-connect':return connectSetupChannel();case'setup-later':captureSetupForm();await saveSetup(true);if(state.setup.index+1<state.setup.value.channels.length)state.setup.index++;else state.setup.stage='complete';return render();case'setup-resume':state.setup.stage='editing';state.setup.step=3;state.setup.index=Math.max(0,state.setup.value.channels.findIndex(row=>!setupStatus(row.channel)));return render();case'remove-config-channel':{const app=selectedApp(button.dataset.app);if(!app)return;if(!confirm('从'+appName(app)+'移除'+names[button.dataset.channel]+'渠道？只影响以后的发布，已有记录和本地凭据会保留。'))return;await api('apps.save',{app:{...app,channels:app.channels.filter(row=>row.channel!==button.dataset.channel)},replace:true});state.setup.value.channels=state.setup.value.channels.filter(row=>row.channel!==button.dataset.channel);state.setup.index=Math.max(0,Math.min(state.setup.index,state.setup.value.channels.length-1));await refreshApps();await saveSetup(true);toast('渠道已移除，已有发布记录仍保留。');return render();}case'new-release':return startNewRelease(button.dataset.app);case'fresh-release':closeModal();return location.hash='#/publish/'+encodeURIComponent(button.dataset.app)+'?new=1';case'edit-release':return editRelease(button.dataset.release);case'publish-check':return beginChecks();case'publish-recheck':return recheck();case'publish-edit':invalidatePublish();state.publish.phase='materials';return render();case'publish-submit':return confirmSubmit();case'retry-cancel':return location.hash='#/release/'+encodeURIComponent(state.publish.releaseId);case'retry-channel':return retryChannel(button.dataset.release,button.dataset.channel);case'check-result':return startJob('releases.reconcile',{release_id:button.dataset.release,channels:[button.dataset.channel]},{kind:'query',appId:button.dataset.app});case'refresh-release':autoRefresh.set(button.dataset.release,Date.now());return startJob('releases.get',{release_id:button.dataset.release,refresh:true},{kind:'query',appId:state.release?.project_id});case'fix-account':return fixAccount(button.dataset.app,button.dataset.channel,button.dataset.release);case'edit-channel':return location.hash='#/setup/'+encodeURIComponent(button.dataset.app)+'?channel='+button.dataset.channel+'&return=publish';case'check-channel':return startJob('apps.check',{app_id:button.dataset.app,channels:[button.dataset.channel]},{kind:'overview',appId:button.dataset.app});case'manual':return openManual(button.dataset.release,button.dataset.channel);case'doctor':state.diagnostic=await api('doctor');return render();case'doctor-repair':return startJob('doctor.repair',{},{});case'forget':{const row=state.accounts.find(item=>item.channel===button.dataset.channel&&item.account===button.dataset.account);if(!confirm('清除'+names[row.channel]+'这个账号的本地凭据？受影响应用：'+((row.app_names||row.apps.map(appName)).join('、')||'无')+'。发布记录和未完成的请求记录会保留。'))return;await api('accounts.forget',{channel:row.channel,account:row.account});state.accounts=(await api('accounts.list')).accounts||[];await refreshApps();toast('本地凭据已清除。再次提交前，请填写凭据并检查账号访问。');return render();}}};void execute().catch(error=>{state.notice={type:'error',text:error.message||'操作未完成，已有资料仍保留。'};render();});});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if((event.key==='Enter'||event.key===' ')&&event.target.classList.contains('file-picker')){event.preventDefault();document.getElementById(event.target.htmlFor).click();}const dialog=$('.modal-dialog');if(event.key==='Tab'&&dialog){const controls=[...dialog.querySelectorAll('button,input,textarea,select,[tabindex]')].filter(control=>!control.disabled&&control.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('pagehide',()=>{closeModal();flushDrafts();});
window.addEventListener('beforeunload',()=>{closeModal();flushDrafts();});
window.addEventListener('hashchange',()=>void navigate());
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void pollJobs();});
async function bootstrap(){try{const [apps,accounts,jobs,draft]=await Promise.all([api('apps.list'),api('accounts.list'),api('jobs.list'),api('drafts.get',{kind:'app',id:'new-app'})]);state.apps=apps.apps||[];state.overviews=apps.overviews||[];state.accounts=accounts.accounts||[];state.jobs=jobs.jobs||[];state.newAppDraft=draft.draft;for(const job of state.jobs)if(!running(job))handledJobs.add(job.id);await navigate();setInterval(()=>void pollJobs(),1200);void pollJobs();}catch(error){state.notice={type:'error',text:error.message||'本地服务暂时不可用，请重新打开页面。'};render();}}
void bootstrap();
